var ISSUE_ENRICH_WORKER_SOURCE = [
    'function(args) {',
    "    var mod = require('./common/smProvider.js');",
    "    var p = mod.createSmProvider({ scm: { provider: 'github' }, repository: args.repo, preseed: args.preseed });",
